            "id": "B_GUARANTEE",
            "issue": "戊的保证期间与行权",
            "supported_state": "戊为连带责任保证人。其未书面同意展期，保证期间仍按原到期日计算六个月，于2023-07-12届满；首次请求于2023-07-18到达，已在期间之外，题设支持戊不再承担保证责任。该结论不是B主债务无效或全部消灭。",
            "fact_refs": ["S06"],
            "rule_refs": ["civil-code-2020:688", "civil-code-2020:692", "civil-code-2020:693", "civil-code-2020:695"]
          },
